605	          <thead><tr><th>Loop</th><th>Carried by</th><th>Today</th><th>Should trigger on</th></tr></thead>
606	          <tbody>
607	            <tr>
608	              <td class="defect">proof finding → structural fix</td>
609	              <td><span class="tag">canon:architect</span></td>
610	              <td>manual routing</td>
