615	              <td><span class="tag">canon:drafter</span> → <span class="tag">vector:planner</span> amend</td>
616	              <td>already automatic mid-build</td>
617	              <td>keep as default path, not a fallback</td>
618	            </tr>
619	            <tr>
620	              <td class="defect">spec decays vs. code over time</td>
621	              <td><span class="tag">canon:drift-checker</span></td>
622	              <td>on-demand only</td>
623	              <td>before extending a spec area untouched N sessions</td>
624	            </tr>
625	            <tr>
626	              <td class="defect">duplicate / overlapping requirement</td>
627	              <td><span class="tag">graph:audit-backlog</span></td>
628	              <td>on-demand only</td>
629	              <td>before graph hands a requirement to canon</td>
630	            </tr>
631	            <tr>
