python3 -c "
import re, glob, hashlib

# 1. Constitution byte-identity check across ALL agents
constitutions = {}
for f in sorted(glob.glob('plugins/*/agents/*.md')):
    content = open(f).read()
    m = re.search(r'<constitution>\n(.*?)\n</constitution>', content, re.S)
    if not m:
        print('MISSING CONSTITUTION:', f)
        continue
    h = hashlib.sha256(m.group(1).encode()).hexdigest()
    constitutions.setdefault(h, []).append(f)

if len(constitutions) > 1:
    print('CONSTITUTION MISMATCH — %d distinct versions found:' % len(constitutions))
    for h, files in constitutions.items():
        print(' group', h[:8], '->', len(files), 'files, e.g.', files[0])
else:
    print('Constitution byte-identical across all', sum(len(v) for v in constitutions.values()), 'agents: OK')
"

python3 -c "
import re, glob

banned_words = ['delve','leverage','seamless','robust','elevate','foster','unlock','empower','testament','pivotal','showcase','tapestry','landscape','underscore','meticulous','game-changer','cutting-edge','unprecedented','transformative','utilize','dive into','supercharge']

files = sorted(glob.glob('plugins/*/agents/*.md')) + sorted(glob.glob('plugins/*/skills/*/SKILL.md')) + sorted(glob.glob('plugins/*/README.md')) + ['README.md', 'CONTRIBUTING.md', 'ARCHITECTURE.md']

issues = []
for f in files:
    try:
        content = open(f).read()
    except FileNotFoundError:
        continue
    low = content.lower()
    for w in banned_words:
        if w in low:
            issues.append((f, w))
    # banned structures
    if re.search(r\"isn't just\b.{0,80}\bit's\b\", content, re.I):
        issues.append((f, 'isnt-just-its structure'))

if issues:
    print('BANNED WORD/STRUCTURE HITS:')
    for f, w in issues:
        print(' ', f, '->', w)
else:
    print('No banned words/structures found across', len(files), 'files checked: OK')
"

python3 -c "
import re, glob
bad = []
for f in sorted(glob.glob('plugins/*/agents/*.md')):
    content = open(f).read()
    m = re.search(r'description: >-\n((?:  .*\n)+)', content)
    if not m:
        bad.append((f, 'NO DESCRIPTION MATCHED'))
        continue
    desc = ' '.join(l.strip() for l in m.group(1).splitlines())
    n = len(desc.split())
    if not (80 <= n <= 200):
        bad.append((f, n))
if bad:
    for f, n in bad: print(f, n)
else:
    print('All 38 agent descriptions within 80-200 words: OK')
"

