    --mono-void: #0a0d11;
    --mono-void-raised: #10151b;
    --mono-line: #263230;
    --mono-ink: #dbe6e2;
    --mono-ink-faint: #6d7d77;
    --mono-trace: #46e6c4;
    --mono-gate: #ffb454;

    --font-display: "Space Mono", ui-monospace, "SF Mono", Menlo, monospace;
    --font-body: "Archivo", system-ui, -apple-system, "Segoe UI", sans-serif;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --ground: #0b0f13;
      --surface: #131920;
      --ink: #e7ece9;
      --ink-soft: #9fb0a9;
      --ink-faint: #667670;
      --trace: #46e6c4;
      --trace-soft: #10302b;
      --gate: #ffb454;
      --gate-soft: #2c2210;
      --line: #202a27;
      --shadow: rgba(0, 0, 0, 0.4);
    }
  }
  :root[data-theme="dark"] {
    --ground: #0b0f13;
    --surface: #131920;
    --ink: #e7ece9;
    --ink-soft: #9fb0a9;
    --ink-faint: #667670;
    --trace: #46e6c4;
    --trace-soft: #10302b;
    --gate: #ffb454;
    --gate-soft: #2c2210;
    --line: #202a27;
    --shadow: rgba(0, 0, 0, 0.4);
  }

  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    * { animation: none !important; transition: none !important; }
  }
  body {
    margin: 0;
    background: var(--ground);
    color: var(--ink);
    font-family: var(--font-body);
    font-size: 16.5px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }
  a { color: var(--trace); }
  code, .mono { font-family: var(--font-display); }

  /* ============ HERO ============ */
  .hero {
    position: relative;
    background: var(--mono-void);
    color: var(--mono-ink);
    overflow: hidden;
    padding: 5.5rem 6vw 4.5rem;
  }
  .hero-trace {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.9;
  }
  .hero-trace path.line {
    fill: none;
    stroke: var(--mono-trace);
    stroke-width: 1.6;
    stroke-dasharray: 6 10;
    opacity: 0.55;
    animation: drift 26s linear infinite;
  }
  @keyframes drift { to { stroke-dashoffset: -640; } }
  .hero-trace circle.node { fill: var(--mono-void); stroke: var(--mono-trace); stroke-width: 1.6; }
  .hero-trace circle.gatept { fill: var(--mono-gate); }
  .hero-inner { position: relative; max-width: 1180px; margin: 0 auto; }
  .eyebrow {
    font-family: var(--font-display);
    font-size: 0.74rem;
