    display: flex;
    gap: 0.6rem;
    align-items: center;
    margin-bottom: 1.6rem;
  }
  .eyebrow .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--mono-trace); box-shadow: 0 0 8px var(--mono-trace); }
  h1 {
    font-family: var(--font-display);
    font-weight: 700;
