from html.parser import HTMLParser

class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.issues = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','path','circle','rect','line','stop','use'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
    def handle_startendtag(self, tag, attrs):
        pass
    def handle_endtag(self, tag):
        if not self.stack:
            self.issues.append(f'Stray closing </{tag}> with empty stack')
            return
        if self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            # mismatched — pop until found
            idx = len(self.stack) - 1 - self.stack[::-1].index(tag)
            unclosed = self.stack[idx+1:]
            self.issues.append(f'</{tag}> closed while {unclosed} were still open (line {self.getpos()[0]})')
            self.stack = self.stack[:idx]
        else:
            self.issues.append(f'</{tag}> with no matching open tag (line {self.getpos()[0]})')

c = open('shift-left-gates.html').read()
p = Checker()
p.feed(c)
print('Unclosed at EOF:', p.stack)
print('Issues:', len(p.issues))
for i in p.issues[:30]:
    print(' -', i)
"

