file.content:
/* ============ HERO ============ */
.hero {
  position: relative;
  background: var(--mono-void);
  color: var(--mono-ink);
  overflow: hidden;
  padding: 5.5rem 6vw 6.5rem;
}
/* Confined to a fixed-height readout strip along the hero's floor — never the
   full-bleed background the text sits on, so its geometry can't drift into
   the text column at any viewport width. Fades in from the void via mask,
   rather than a hard edge, so it reads as ambient signal, not stray artwork. */
.hero-trace {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 68px;
  opacity: 0.8;
  mask-image: linear-gradient(to bottom, transparent, black 40%);
  -webkit-mask-image: linear-gradient(to bottom, transparent, black 40%);
}
.hero-trace path.line {
  fill: none;
  stroke: var(--mono-trace);
  stroke-width: 1.6;
  stroke-dasharray: 6 10;
  opacity: 0.5;
  animation: drift 26s linear infinite;
}
@keyframes drift { to { stroke-dashoffset: -640; } }
.hero-trace rect.node { fill: var(--mono-void); stroke: var(--mono-trace); stroke-width: 1.6; }
.hero-trace rect.gatept { fill: var(--mono-gate); stroke: none; }
.hero-inner { position: relative; max-width: 1180px; margin: 0 auto; }
.eyebrow {
  font-family: var(--font-display);
  font-size: 0.74rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--mono-trace);

