<style>
  :root {
    --void: #F7F7F9;
    --panel: #FFFFFF;
    --panel-2: #EFF0F4;
    --hairline: #E3E4EA;
    --hairline-strong: #C7C9D3;
    --ink: #14161C;
    --ink-dim: #52555E;
    --ink-faint: #84878F;
    --amber: #A0600D;
    --amber-dim: #FBF0DE;
    --cyan: #0E8C7C;
    --cyan-dim: #E1F4F0;
    --coral: #BC3A57;
    --coral-dim: #FBE9EF;
    --violet: #5A45D6;
    --violet-dim: #EEECFC;
    --shadow: 0 1px 2px rgba(20,22,30,0.05), 0 4px 14px rgba(20,22,30,0.04);
  }

  * { box-sizing: border-box; }
  html { -webkit-text-size-adjust: 100%; }
  body {
    margin: 0; background: var(--void); color: var(--ink);
    font-family: "Public Sans", ui-sans-serif, system-ui, sans-serif;
    font-size: 16px; line-height: 1.6; -webkit-font-smoothing: antialiased;
  }
  a { color: var(--violet); text-decoration-thickness: 1px; text-underline-offset: 3px; }
  a:focus-visible, button:focus-visible, summary:focus-visible {
    outline: 2px solid var(--violet); outline-offset: 2px; border-radius: 4px;
  }
  code { font-family: "Chivo Mono", monospace; font-size: 0.9em; color: var(--ink); background: var(--panel-2); padding: 0.15em 0.4em; border-radius: 5px; }

  /* ---------- Status bar ---------- */
  .statusbar {
    font-family: "Chivo Mono", monospace; font-size: 0.74rem; letter-spacing: 0.1em; text-transform: uppercase;
    color: var(--ink-faint); border-bottom: 1px solid var(--hairline);
    padding: 0.6rem clamp(1rem, 3vw, 2rem); display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap;
  }
  .statusbar .live { color: var(--violet); }

  /* ---------- Shell ---------- */
  .shell { display: flex; max-width: 1440px; margin: 0 auto; align-items: flex-start; }

  .rail {
