    border-right: 1px solid var(--hairline); padding: 1.8rem 1.2rem 2rem; display: flex; flex-direction: column; gap: 2rem;
  }
  @media (max-width: 980px) { .rail { display: none; } }
  .rail-brand { display: flex; align-items: center; gap: 0.55rem; }
  .rail-brand svg { color: var(--violet); flex: none; }
  .rail-brand b { font-family: "Chivo", sans-serif; font-weight: 900; font-size: 0.92rem; letter-spacing: -0.01em; }
  .flightplan { display: flex; flex-direction: column; gap: 0.1rem; }
  .flightplan a {
    display: flex; gap: 0.65rem; align-items: baseline; padding: 0.5rem 0.6rem; border-radius: 8px;
    color: var(--ink-dim); text-decoration: none; font-size: 0.85rem; border-left: 2px solid transparent;
  }
  .flightplan a:hover, .flightplan a:focus-visible { background: var(--violet-dim); color: var(--ink); border-left-color: var(--violet); }
  .flightplan a .n { font-family: "Chivo Mono", monospace; font-size: 0.76rem; color: var(--ink-faint); }
  .rail-foot { margin-top: auto; font-family: "Chivo Mono", monospace; font-size: 0.74rem; color: var(--ink-faint); line-height: 1.7; border-top: 1px solid var(--hairline); padding-top: 1rem; }

