from html.parser import HTMLParser
class Checker(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.issues=[]
        self.void={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void: self.stack.append(tag)
    def handle_endtag(self, tag):
        if not self.stack: self.issues.append(f'stray </{tag}>'); return
        if self.stack[-1]==tag: self.stack.pop()
        elif tag in self.stack:
            idx=len(self.stack)-1-self.stack[::-1].index(tag)
            self.issues.append(f'</{tag}> mismatch'); self.stack=self.stack[:idx]
        else: self.issues.append(f'</{tag}> no match')
c=open('shift-left-gates.html').read()
p=Checker(); p.feed(c)
print('unclosed:', p.stack, 'issues:', len(p.issues))
"

